function externalFixture(read) {
  const opened = []; const failures = []; const frame = { url: documentUrl }; const contents = { mainFrame: frame, executeJavaScript: read, isDestroyed: () => false, getZoomFactor: () => 1 }; const window = { webContents: contents, isDestroyed: () => false };
  const boundary = _createExternalLinkHandler({ window, documentUrl, openExternal: async (url) => { opened.push(url); }, showFailure: async (message) => { failures.push(message); } }); return { boundary, opened, failures, frame };
}
const externalDetails = (url = 'https://example.com/docs') => ({ url, frameName: 'handwell-external-link', disposition: 'foreground-tab' });
const externalAnchor = (url = 'https://example.com/docs') => ({ href: url, target: 'handwell-external-link', documentUrl });

test('external URL boundary rejects unsafe schemes, credentials, encoded controls and normalization tricks', () => {
  for (const url of ['javascript:alert(1)', 'vbscript:bad', 'data:text/html,hi', 'file:///private/file', 'mailto:a@example.com', '//example.com', 'https://u:p@example.com/', 'https://example.com/%0a', 'https://example.com/%250a', 'https:\\example.com', 'https://example.com/\t']) assert.equal(_externalLinkUrl(url), null, url);
  assert.equal(_externalLinkUrl('https://example.com/a%20b'), 'https://example.com/a%20b'); assert.equal(_externalLinkUrl('http://localhost:8123/'), 'http://localhost:8123/');
});

test('external handler requires one physical anchor activation bound to exact URL; arbitrary clicks and programmatic opens stay denied', async () => {
  let target = externalAnchor(); const fixture = externalFixture(async () => target); const { boundary, opened } = fixture; assert.deepEqual(boundary.handler(externalDetails()), { action: 'deny' }); await new Promise((resolve) => setImmediate(resolve)); assert.deepEqual(opened, []);
  boundary.beforeMouse({}, { type: 'mouseDown', button: 'left', x: 10, y: 20 }); boundary.beforeMouse({}, { type: 'mouseUp', button: 'left', x: 10, y: 20 }); assert.deepEqual(boundary.handler(externalDetails()), { action: 'deny' }); await new Promise((resolve) => setImmediate(resolve)); assert.deepEqual(opened, ['https://example.com/docs']);
  boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1);
  target = null; boundary.beforeMouse({}, { type: 'mouseDown', button: 'left', x: 5, y: 5 }); boundary.beforeMouse({}, { type: 'mouseUp', button: 'left', x: 5, y: 5 }); boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1);
  target = externalAnchor(); boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: false, isAutoRepeat: false }); boundary.handler(externalDetails('https://different.example.com/')); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1); boundary.close();
});

test('Enter activation remains bound to this live main frame and closes revoke pending external gestures', async () => {
  const fixture = externalFixture(async () => externalAnchor()); const { boundary, opened, frame } = fixture; boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: true, isAutoRepeat: false }); boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 0);
  boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: false, isAutoRepeat: false }); boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1);
  boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: false, isAutoRepeat: false }); frame.url = 'https://foreign.example.com/'; boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1); frame.url = documentUrl;
  boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: false, isAutoRepeat: false }); boundary.close(); boundary.handler(externalDetails()); await new Promise((resolve) => setImmediate(resolve)); assert.equal(opened.length, 1);
});

test('a genuine external activation with failed OS opener shows a bounded safe failure and never creates an Electron window', async () => {
  const messages = []; const window = { isDestroyed: () => false, webContents: { mainFrame: { url: documentUrl }, isDestroyed: () => false, executeJavaScript: async () => externalAnchor() } }; const boundary = _createExternalLinkHandler({ window, documentUrl, openExternal: async () => { throw new Error('raw secret failure'); }, showFailure: async (message) => { messages.push(message); } }); boundary.beforeInput({}, { type: 'keyDown', key: 'Enter', isComposing: false, isAutoRepeat: false }); assert.deepEqual(boundary.handler(externalDetails()), { action: 'deny' }); await new Promise((resolve) => setImmediate(resolve)); assert.equal(messages.length, 1); assert.equal(messages[0].includes('secret'), false); assert.match(messages[0], /原始回复.*复制网址/u); boundary.close();
});


