test('getState carries Shell status without private command, review text, output or publication bytes', async () => { const request=new ShellRequest({requestId:'request-shell',runId:'original-run',command:'printf private-shell-command',reason:'当前任务'});const at='2026-10-10T00:00:00.000Z';const journal=enqueueShellWorkflow(createShellWorkflow(projectId),{id:request.requestId,revision:1,request,requestDigest:request.digest,origin:{projectId,roleId:'Builder',taskId:'task1',sessionId:'s',instanceId:'i',runId:request.runId},bindings:{planDigest:plan.planDigest,organizationDigest:'a'.repeat(64),organizationVersion:'customer-v1',roleDigest:'b'.repeat(64),roleRevision:1,profileVersion:'c'.repeat(64),contextSnapshotDigest:'d'.repeat(64),fileOwnersDigest:'e'.repeat(64),epoch:1},preparation:null,status:'pending',review:null,reviewer:null,reviewText:'private-review',output:{stdout:'private-shell-output',stderr:'',truncated:false},result:null,publication:null,createdAt:at,expiresAt:'2026-10-10T00:05:00.000Z',updatedAt:at});const value={...dto,...governedDTO({organization:createOrganization(projectId),ledger:createRoleProposalLedger(projectId),queue:createInteractionQueue(projectId),timeline:createConversationTimeline(projectId),evidence:[],acceptances:[],repairs:[],shellWorkflow:journal})};const pipeline={getState:async()=>({ok:true,value})};let result=await _dispatchDesktopIpc(event,window,documentUrl,'getState',{},pipeline);assert.equal(result.ok,true);assert.equal(result.value.shellRequests[0].status,'pending');for(const privateText of ['private-shell-command','private-review','private-shell-output'])assert.equal(JSON.stringify(result).includes(privateText),false);for(const forbidden of [{publicationReceipt:'private'},{contentBase64:'private'},{recovery:{apiKey:'private'}}]){pipeline.getState=async()=>({ok:true,value:{...value,shellRequests:[{...value.shellRequests[0],...forbidden}]}});result=await _dispatchDesktopIpc(event,window,documentUrl,'getState',{},pipeline);assert.equal(result.ok,false);assert.equal(JSON.stringify(result).includes('private'),false);}assert.equal(WB_OPERATIONS.includes('approveShell'),false);assert.equal(WB_OPERATIONS.includes('executeShell'),false); });
import { createRoleMemories, saveRoleMemory, createConversationTimeline, createInteractionQueue } from '../../src/models/interaction.mjs';
import { createRoleProposalLedger } from '../../src/models/organization.mjs';
test('role memory statistics and safe notices survive Pipeline DTO to real IPC reconstruction without private source values', async () => {
  const memories = saveRoleMemory(createRoleMemories(projectId), { roleId: 'ProjectManager', expectedRevision: 0, summary: 'private-summary-value', covered: [], messages: [{ sourceId: 'a'.repeat(64), sourceDigest: 'b'.repeat(64), role: 'user', text: 'private-source-value' }], sourceDigest: 'c'.repeat(64), updatedAt: '2026-10-09T00:00:00.000Z' });
  const domain = { organization: createOrganization(projectId), ledger: createRoleProposalLedger(projectId), queue: createInteractionQueue(projectId), evidence: [], acceptances: [], repairs: [], timeline: createConversationTimeline(projectId), memberConversations: createMemberConversations(projectId), roleMemories: memories };
  const value = { ...dto, ...governedDTO(domain), memoryNotices: [{ roleId: 'ProjectManager', code: 'role_memory_summary_failed', message: 'private-sdk-error' }] };
  const pipeline = { getState: async () => ({ ok: true, value }) }; const result = await _dispatchDesktopIpc(event, window, documentUrl, 'getState', {}, pipeline); assert.equal(result.ok, true); assert.equal(result.value.roleMemory.entries.length, 1); assert.equal(result.value.roleMemory.entries[0].recentMessages, 1); assert.equal(result.value.memoryNotices[0].code, 'role_memory_summary_failed'); for (const privateText of ['private-summary-value', 'private-source-value', 'private-sdk-error', 'sourceDigest', 'roleMemories']) assert.equal(JSON.stringify(result).includes(privateText), false);
});
test('original getState IPC carries only explicit legal absence and rejects present/null and conflicting deletion fields', async () => {
  const input={resource:'obsolete.txt',state:'absent',sha256:null,byteLength:0};const value={...dto,organization:createOrganization(projectId),evidence:[{id:'e',roleId:'Acceptance',taskId:'t',planDigest:'a'.repeat(64),result:{checkId:'c',status:'passed',reason:'tests_passed',executed:true,testCount:1,exitCode:0,inputVersions:[input],stdout:'',stderr:'',startedAt:'2026-10-10T00:00:00.000Z',finishedAt:'2026-10-10T00:00:01.000Z',logsTruncated:false,environment:{platform:'darwin',runtime:'node',runtimeVersion:'24',isolation:'actual-no-child',network:'none'}}}]};const pipeline={getState:async()=>({ok:true,value})};let result=await _dispatchDesktopIpc(event,window,documentUrl,'getState',{},pipeline);assert.equal(result.ok,true);assert.deepEqual(result.value.evidence[0].result.inputVersions,[input]);
  for(const bad of [{...input,state:undefined},{...input,state:'present'},{...input,byteLength:1},{...input,executable:false}]){value.evidence[0].result.inputVersions=[bad];result=await _dispatchDesktopIpc(event,window,documentUrl,'getState',{},pipeline);assert.equal(result.ok,false);}
});
